contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint256 amount) public payable {
        require(target != address(0), "target must be nonzero");
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balanceOf(target); if (__ESBMC_reverted()) return;
        bool reverted;
        c.mintToken(target, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted ? (c.totalSupply() == supplyBefore && c.balanceOf(target) == balBefore)
                        : (c.totalSupply() == supplyBefore + amount && c.balanceOf(target) == balBefore + amount));
    }

    receive() external payable {}
}

